S = "Hakeem Force Academy"
QS = [
(S, "Which letter is missing in the alphabet sequence L, _, N, O?", ["K", "M", "P", "J"], 1, "The letters of the alphabet run in order: L, M, N, O. So M is missing.", "The English alphabet has 26 letters.", [1285]),
(S, "Who headed the Cripps Mission sent to India in 1942?", ["Lord Wavell", "Sir Stafford Cripps", "Lord Mountbatten", "Lord Linlithgow"], 1, "The mission was led by Sir Stafford Cripps, a member of the British War Cabinet. It offered India dominion status after World War II.", "Both the Congress and the Muslim League rejected the Cripps proposals.", [4440]),
(S, "What is the mode of the numbers 3, 3, 4, 5, 6?", ["3", "4", "5", "6"], 0, "The mode is the value that appears most often. The number 3 appears twice and all others appear once.", "The median of this set is 4.", [1133]),
(S, "To which age do the people of the Indus Valley Civilization belong?", ["Old Stone Age", "Modern Age", "Bronze Age", "Iron Age"], 2, "The Indus Valley people used copper and bronze tools, so the civilization belongs to the Bronze Age.", "The civilization is also called the Harappan Civilization.", [3858]),
(S, "For what were the people of Mohenjo-daro and Harappa famous?", ["Well-planned cities with a drainage system", "Building pyramids", "Writing the Vedas", "Making iron weapons"], 0, "Their cities had straight streets, brick houses and covered drains. This shows advanced town planning.", "The Great Bath is a famous building of Mohenjo-daro.", [1743, 2917]),
(S, "What was the main occupation of the people of Harappa and Mohenjo-daro?", ["Agriculture and trade", "Hunting only", "Sea piracy", "Iron mining"], 0, "The people grew wheat and barley and traded with Mesopotamia and other lands.", "Cotton was probably first grown in the Indus region.", [3544]),
(S, "Approximately when did the Mohenjo-daro civilization flourish?", ["About 2500 BC", "About 500 BC", "About 1000 AD", "About 5000 BC"], 0, "The mature Indus Valley Civilization flourished from about 2600 to 1900 BC. A common round date for Mohenjo-daro is 2500 BC.", "Mohenjo-daro was rediscovered in 1922 by R. D. Banerji.", [3079]),
(S, "If the first day of a month is Monday, what day will the 21st day be?", ["Saturday", "Sunday", "Monday", "Tuesday"], 1, "The 21st is 20 days after the 1st. 20 divided by 7 leaves remainder 6, and Monday plus 6 days is Sunday.", "A week has 7 days, so the same weekday repeats every 7 days.", [906]),
(S, "If the first day of a month is Monday, what day will the eighth day be?", ["Sunday", "Monday", "Tuesday", "Saturday"], 1, "The 8th is exactly 7 days after the 1st, so it falls on the same weekday, Monday.", "The 15th, 22nd and 29th are also Mondays.", [2013]),
(S, "Days, weeks and months are units of what?", ["Time", "Distance", "Weight", "Speed"], 0, "Days, weeks and months are used to measure time.", "The SI unit of time is the second.", [1685]),
(S, "Which strait separates Morocco in Africa from Europe (Spain)?", ["Strait of Hormuz", "Strait of Gibraltar", "Bosphorus", "Bab-el-Mandeb"], 1, "The Strait of Gibraltar joins the Mediterranean Sea with the Atlantic Ocean and lies between Morocco and Spain.", "It is only about 14 km wide at its narrowest point.", [4307]),
(S, "Which is regarded as the first mosque on earth?", ["Masjid al-Haram (Kaaba), Makkah", "Masjid-e-Nabawi", "Masjid al-Aqsa", "Quba Mosque"], 0, "Most Islamic sources say the Kaaba in Makkah was the first house of worship built for people. Quba Mosque is the first mosque built in Islam by the Prophet (PBUH).", "Masjid al-Aqsa was built 40 years after the Kaaba according to a hadith.", [4353]),
(S, "What is the name of Allama Iqbal's mother?", ["Imam Bibi", "Aamna Bibi", "Fatima Bibi", "Sakina Bibi"], 0, "Allama Iqbal's mother was Imam Bibi, and his father was Sheikh Noor Muhammad.", "Iqbal was born in Sialkot on 9 November 1877.", [3229]),
(S, "What is the name of the force that opposes the motion between two bodies in contact?", ["Gravity", "Friction", "Tension", "Magnetism"], 1, "Friction acts between touching surfaces and opposes their relative motion.", "Friction produces heat.", [3243]),
(S, "What is an electric motor?", ["A device that changes electrical energy into mechanical energy", "A device that changes mechanical energy into electrical energy", "A device that stores charge", "A device that raises voltage"], 0, "An electric motor uses a current in a magnetic field to produce rotation. This turns electrical energy into mechanical energy.", "A generator does the opposite job of a motor.", [2886]),
(S, "Who is credited with inventing the electric motor?", ["Thomas Edison", "Michael Faraday", "Alexander Graham Bell", "James Watt"], 1, "Michael Faraday demonstrated the first electric motor in 1821, and most textbooks credit him.", "Other inventors such as Jedlik, Jacobi and Davenport also built early motors, so sources differ.", [4404, 4405, 119, 221, 769]),
(S, "The M-8 Motorway links Gwadar with which city?", ["Ratodero", "Multan", "Hyderabad", "Peshawar"], 0, "The M-8 runs from Ratodero in Sindh through Khuzdar, Awaran and Hoshab to near Gwadar.", "It is about 890 km long and is part of the CPEC western route; only parts are complete.", [2643]),
(S, "Suo motu notice by the Supreme Court of Pakistan is taken under which article of the Constitution?", ["Article 184(3)", "Article 25", "Article 62", "Article 245"], 0, "Article 184(3) gives the Supreme Court original jurisdiction on matters of public importance involving fundamental rights.", "Suo motu is a Latin term meaning on its own motion.", [2593, 2715]),
(S, "Which is called the highest battlefield in the world?", ["Siachen Glacier", "Kargil", "Waziristan", "Khyber Pass"], 0, "The Siachen Glacier in the Karakoram, at about 5,400 m, is the highest battleground.", "India and Pakistan have faced each other there since 1984.", [3126]),
(S, "How many peaks above 8000 metres are located in Pakistan?", ["Two", "Three", "Five", "Eight"], 2, "Pakistan has five: K2, Nanga Parbat, Gasherbrum I, Broad Peak and Gasherbrum II.", "Four of them lie in the Karakoram and Nanga Parbat lies in the Himalayas.", [873]),
(S, "Who founded the Pakistan National Movement in 1933?", ["Chaudhry Rehmat Ali", "Allama Iqbal", "Liaquat Ali Khan", "Maulana Muhammad Ali Jauhar"], 0, "Chaudhry Rehmat Ali launched the Pakistan National Movement in Cambridge, and his pamphlet Now or Never (1933) proposed the name Pakistan.", "He was a student at Cambridge University.", [4424]),
(S, "A train moves at twice the speed of a car, and the car moves at 60 km/h. How far will the train go in 12 minutes?", ["12 km", "24 km", "30 km", "48 km"], 1, "Train speed is 2 x 60 = 120 km/h. In 12 minutes (12/60 = 0.2 hour) it covers 120 x 0.2 = 24 km.", "To change minutes to hours, divide by 60.", [562]),
(S, "A person sitting in a moving train throws a ball vertically upwards. Where will the ball fall?", ["Behind him", "In front of him", "Back into his hand", "Outside the train"], 2, "The ball shares the forward speed of the train, so it keeps moving forward with the train. It therefore lands back in his hand.", "This is an example of Newton's first law of motion (inertia).", [1468]),
(S, "Which dam of Pakistan is made of earth and rock fill and is the largest earth-filled dam in the world?", ["Tarbela Dam", "Mangla Dam", "Diamer-Bhasha Dam", "Warsak Dam"], 0, "Tarbela Dam on the Indus River is mostly built of earth and rock fill and is called the largest earth-filled dam.", "Tarbela was completed in 1976.", [151, 4080, 4084, 4085]),
(S, "Who founded the Mughal Empire in India?", ["Akbar", "Babur", "Humayun", "Shah Jahan"], 1, "Babur defeated Ibrahim Lodhi at the First Battle of Panipat in 1526 and founded the empire.", "The empire lasted formally until 1857.", [749]),
]
